    /// <summary>
    /// Adds the execution guard checks (<see cref="ExecutionGuard"/>, spec §3.6) to a syntax tree: the call check at the
    /// start of every method, local function, accessor, operator, constructor, lambda and anonymous method (expression bodies
    /// become blocks; an expression lambda only when the semantic model says it is a delegate, never part of an expression
    /// tree, and free of errors); a counter before every
    /// loop and its check at the start of the body; the jump check before every <c>goto</c>; the catch filter on every
    /// <c>catch</c>.
    /// Every inserted piece sits on lines of its own, followed by a <c>#line</c> directive and padding that put the agent's
    /// code back on its own line AND column: diagnostics and stack frames keep the agent's coordinates.
    /// </summary>
    internal static class GuardWriter
    {
        const string CounterPrefix = "__codeExecLoop";
        const string InitPrefix = "__codeExecInit";

        // Guard fields of partial classes must not collide across trees: a process-wide counter names them.
        static int _initFields;

        /// <summary>
        /// Text inserted at <see cref="Position"/> (after removing <see cref="Remove"/> characters there), its line mapped like
        /// <see cref="MapTo"/>. Openers sort outer first, closers (the end of a wrap) inner first and before openers.
        /// </summary>
        readonly struct Edit
        {
            public Edit(int position, string text, int mapTo, int order, bool closer = false, int remove = 0)
            {
                Position = position;
                Text = text;
                MapTo = mapTo;
                Order = order;
                Closer = closer;
                Remove = remove;
            }

            public int Position { get; }
            public string Text { get; }
            public int MapTo { get; }
            public int Order { get; }
            public bool Closer { get; }
            public int Remove { get; }
        }

        /// <summary>
        /// The guarded tree, or <paramref name="tree"/> itself when it has nothing to guard or does not parse. Expression
        /// lambdas are guarded only with a <paramref name="compilation"/> that holds <paramref name="tree"/>: it tells
        /// delegates from expression trees and what they return (bound only when the tree has such a lambda).
        /// </summary>
        public static SyntaxTree Write(SyntaxTree tree, Compilation? compilation = null)
        {
            var root = tree.GetRoot();
            if (tree.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error) || tree.FilePath.IndexOf('"') >= 0)
                return tree; // broken code reports its own errors, untouched; a `"` cannot be written in a #line directive
            var edits = new List<Edit>();
            var semantics = compilation == null ? null : new Semantics(compilation, tree);
            foreach (var node in root.DescendantNodes())
            {
                var count = edits.Count;
                Collect(node, edits, semantics);
                if (edits.Count != count && node.Ancestors().Any(a => a is InterpolationSyntax))
                    edits.RemoveRange(count, edits.Count - count); // an interpolation hole may not span lines (C# < 11)
            }
            if (edits.Count == 0)
                return tree;

            var ordered = edits
                .OrderBy(e => e.Position)
                .ThenBy(e => e.Closer ? 0 : 1)
                .ThenBy(e => e.Closer ? -e.Order : e.Order)
                .ToList();
            var text = tree.GetText().ToString();
            var sb = new StringBuilder(text.Length + ordered.Count * 96);
            var last = 0;
            foreach (var edit in ordered)
            {
                sb.Append(text, last, edit.Position - last).Append('\n');
                AppendLine(sb, tree, edit.MapTo);
                sb.Append(edit.Text).Append('\n');
                last = edit.Position + edit.Remove;
                AppendLine(sb, tree, last);
                sb.Append(' ', tree.GetLineSpan(new TextSpan(last, 0)).StartLinePosition.Character);
            }
            sb.Append(text, last, text.Length - last);
            return CSharpSyntaxTree.ParseText(sb.ToString(), (CSharpParseOptions)tree.Options, tree.FilePath, Encoding.UTF8);
        }

        /// <summary>What expression lambdas need of the semantic model, bound on first use: only trees with one pay.</summary>
        sealed class Semantics
        {
            readonly Compilation _compilation;
            readonly SyntaxTree _tree;
            readonly Dictionary<SyntaxNode, bool> _delegates = new Dictionary<SyntaxNode, bool>();
            SemanticModel? _model;
            bool? _hasErrors;

            public Semantics(Compilation compilation, SyntaxTree tree)
            {
                _compilation = compilation;
                _tree = tree;
            }

            public SemanticModel Model => _model ??= _compilation.GetSemanticModel(_tree);

            /// <summary>Code with errors never runs: its expression lambdas stay as written, so its diagnostics stay the agent's.</summary>
            public bool HasErrors => _hasErrors ??= Model.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error);

            /// <summary>
            /// Converted to a delegate type, or to <c>Delegate</c> / <c>MulticastDelegate</c> / <c>object</c> with a delegate
            /// natural type (C# 10); never to an expression tree (<c>Expression&lt;T&gt;</c>, <c>LambdaExpression</c>, ...).
            /// </summary>
            public bool IsDelegate(AnonymousFunctionExpressionSyntax function)
            {
                if (!_delegates.TryGetValue(function, out var isDelegate))
                {
                    var info = Model.GetTypeInfo(function);
                    var target = info.ConvertedType;
                    isDelegate = target?.TypeKind == TypeKind.Delegate
                        || (target != null && info.Type?.TypeKind == TypeKind.Delegate && (target.SpecialType == SpecialType.System_Delegate
                            || target.SpecialType == SpecialType.System_MulticastDelegate || target.SpecialType == SpecialType.System_Object));
                    _delegates[function] = isDelegate;
                }
                return isDelegate;
            }

            /// <summary>Whether an async member's return type is a generic task type, or null when it does not bind.</summary>
            public bool? IsGenericTask(TypeSyntax type) =>
                Model.GetTypeInfo(type).Type is INamedTypeSymbol named && named.TypeKind != TypeKind.Error ? named.Arity > 0 : (bool?)null;
        }

        static void Collect(SyntaxNode node, List<Edit> edits, Semantics? semantics)
        {
            switch (node)
            {
                case WhileStatementSyntax loop:
                    Loop(loop, loop.Statement, edits);
                    break;
                case DoStatementSyntax loop:
                    Loop(loop, loop.Statement, edits);
                    break;
                case ForStatementSyntax loop:
                    Loop(loop, loop.Statement, edits);
                    break;
                case CommonForEachStatementSyntax loop:
                    Loop(loop, loop.Statement, edits);
                    break;
                case GotoStatementSyntax jump:
                    Wrap(jump, ExecutionGuard.JumpCheck, jump.SpanStart, edits);
                    break;
                case CatchClauseSyntax handler when CatchesGuardStops(handler):
                    if (handler.Filter != null)
                    {
                        var filter = handler.Filter.FilterExpression;
                        edits.Add(new Edit(filter.SpanStart, ExecutionGuard.CatchFilter + " && (", filter.SpanStart, edits.Count));
                        edits.Add(new Edit(filter.Span.End, ")", filter.Span.End, edits.Count, closer: true));
                    }
                    else
                    {
                        var end = handler.Declaration?.Span.End ?? handler.CatchKeyword.Span.End;
                        edits.Add(new Edit(end, "when (" + ExecutionGuard.CatchFilter + ")", end, edits.Count));
                    }
                    break;
                case MethodDeclarationSyntax method:
                    Function(method.Body, method.ExpressionBody, method.SemicolonToken, method.ExpressionBody != null && ReturnsValue(method.ReturnType, method.Modifiers, semantics), edits);
                    break;
                case LocalFunctionStatementSyntax function:
                    Function(function.Body, function.ExpressionBody, function.SemicolonToken, function.ExpressionBody != null && ReturnsValue(function.ReturnType, function.Modifiers, semantics), edits);
                    break;
                case OperatorDeclarationSyntax _:
                case ConversionOperatorDeclarationSyntax _:
                    var op = (BaseMethodDeclarationSyntax)node;
                    Function(op.Body, op.ExpressionBody, op.SemicolonToken, true, edits);
                    break;
                case BaseMethodDeclarationSyntax other: // constructors, destructors
                    Function(other.Body, other.ExpressionBody, other.SemicolonToken, false, edits);
                    break;
                case AccessorDeclarationSyntax accessor:
                    Function(accessor.Body, accessor.ExpressionBody, accessor.SemicolonToken, accessor.Keyword.IsKind(SyntaxKind.GetKeyword), edits);
                    break;
                case PropertyDeclarationSyntax property when property.ExpressionBody != null:
                    Getter(property.ExpressionBody, property.SemicolonToken, edits);
                    break;
                case IndexerDeclarationSyntax indexer when indexer.ExpressionBody != null:
                    Getter(indexer.ExpressionBody, indexer.SemicolonToken, edits);
                    break;
                case LambdaExpressionSyntax lambda when lambda.Body is BlockSyntax block:
                    Function(block, null, default, false, edits);
                    break;
                case LambdaExpressionSyntax lambda when lambda.Body is ExpressionSyntax body && semantics != null:
                    ExpressionLambda(lambda, body, semantics, edits);
                    break;
                case AnonymousMethodExpressionSyntax method:
                    Function(method.Block, null, default, false, edits);
                    break;
                case TypeDeclarationSyntax type when type.IsKind(SyntaxKind.ClassDeclaration) || type.IsKind(SyntaxKind.RecordDeclaration):
                    Initializers(type, edits);
                    break;
                case InvocationExpressionSyntax call when semantics != null && call.ArgumentList.Arguments.Count > 0
                    && WorkStartNames.Contains(RightmostName(call.Expression)):
                    Workers(call, call.ArgumentList, semantics, edits);
                    break;
                case ObjectCreationExpressionSyntax creation when semantics != null && creation.ArgumentList != null
                    && (RightmostName(creation.Type) == "Thread" || RightmostName(creation.Type) == "Task"):
                    Workers(creation, creation.ArgumentList, semantics, edits);
                    break;
                case ImplicitObjectCreationExpressionSyntax creation when semantics != null:
                    Workers(creation, creation.ArgumentList, semantics, edits);
                    break;
            }
        }

        /// <summary>The methods that start work on another thread or as a task (with the constructors of Thread and Task).</summary>
        static readonly HashSet<string> WorkStartNames = new HashSet<string> { "Run", "StartNew", "QueueUserWorkItem", "UnsafeQueueUserWorkItem" };

        static string RightmostName(SyntaxNode node) => node switch
        {
            MemberAccessExpressionSyntax member => member.Name.Identifier.ValueText,
            QualifiedNameSyntax qualified => qualified.Right.Identifier.ValueText,
            AliasQualifiedNameSyntax alias => alias.Name.Identifier.ValueText,
            SimpleNameSyntax simple => simple.Identifier.ValueText,
            _ => "",
        };

        /// <summary>
        /// A delegate handed to a thread start becomes <c>Worker((T)(delegate))</c> (<see cref="ExecutionGuard.Worker"/>), one
        /// handed to a task start <c>TaskWorker((T)(delegate))</c>, cast to the delegate type it already converts to, so
        /// overload resolution picks the same method: the work then belongs to the run and stops once the run has ended.
        /// Not inside an expression tree or a query.
        /// </summary>
        static void Workers(ExpressionSyntax call, ArgumentListSyntax arguments, Semantics semantics, List<Edit> edits)
        {
            if (semantics.HasErrors || !(semantics.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method) || !(StartsWork(method) is bool task))
                return;
            foreach (var outer in call.Ancestors())
            {
                if (outer is QueryExpressionSyntax || (outer is AnonymousFunctionExpressionSyntax function && !semantics.IsDelegate(function)))
                    return;
            }
            var entry = task ? ExecutionGuard.TaskWorker : ExecutionGuard.Worker;
            foreach (var argument in arguments.Arguments)
            {
                var expression = argument.Expression;
                if (!argument.RefKindKeyword.IsKind(SyntaxKind.None) || !(semantics.Model.GetTypeInfo(expression).ConvertedType is INamedTypeSymbol type)
                    || !IsWorkDelegate(type, task) || !CanBeNamed(type))
                    continue;
                var cast = type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
                edits.Add(new Edit(expression.SpanStart, entry + "((" + cast + ")(", expression.SpanStart, edits.Count));
                edits.Add(new Edit(expression.Span.End, "))", expression.Span.End, edits.Count, closer: true));
            }
        }

        /// <summary>Whether the method starts work: true for a task start, false for a thread start, null for neither.</summary>
        static bool? StartsWork(IMethodSymbol method)
        {
            switch (method.ContainingType?.OriginalDefinition.ToDisplayString())
            {
                case "System.Threading.Thread":
                    return method.MethodKind == MethodKind.Constructor ? false : (bool?)null;
                case "System.Threading.ThreadPool":
                    return method.Name == "QueueUserWorkItem" || method.Name == "UnsafeQueueUserWorkItem" ? false : (bool?)null;
                case "System.Threading.Tasks.Task<TResult>":
                    return method.MethodKind == MethodKind.Constructor ? true : (bool?)null;
                case "System.Threading.Tasks.Task":
                    return method.MethodKind == MethodKind.Constructor || method.Name == "Run" ? true : (bool?)null;
                case "System.Threading.Tasks.TaskFactory":
                case "System.Threading.Tasks.TaskFactory<TResult>":
                    return method.Name == "StartNew" ? true : (bool?)null;
                default:
                    return null;
            }
        }

        /// <summary>The delegate types <see cref="ExecutionGuard.Worker"/> (thread starts) or <see cref="ExecutionGuard.TaskWorker"/> have an overload for.</summary>
        static bool IsWorkDelegate(INamedTypeSymbol type, bool task)
        {
            switch (type.OriginalDefinition.ToDisplayString())
            {
                case "System.Action<T>":
                    return true;
                case "System.Threading.ThreadStart":
                case "System.Threading.ParameterizedThreadStart":
                case "System.Threading.WaitCallback":
                    return !task;
                case "System.Action":
                case "System.Func<TResult>":
                case "System.Func<T, TResult>":
                    return task;
                default:
                    return false;
            }
        }

        /// <summary>Whether the type can be written in source: no anonymous or erroneous type anywhere in it.</summary>
        static bool CanBeNamed(ITypeSymbol type)
        {
            if (type.IsAnonymousType || type.TypeKind == TypeKind.Error)
                return false;
            if (type is IArrayTypeSymbol array)
                return CanBeNamed(array.ElementType);
            if (type is IPointerTypeSymbol)
                return false;
            return !(type is INamedTypeSymbol named) || named.TypeArguments.All(CanBeNamed);
        }

        /// <summary>
        /// Field and property initializers run before any constructor body (and with no constructor at all): a class with
        /// them gets a first field of its own whose initializer runs the call check (static ones a static field).
        /// </summary>
        static void Initializers(TypeDeclarationSyntax type, List<Edit> edits)
        {
            bool instance = false, shared = false;
            foreach (var member in type.Members)
            {
                bool initialized;
                if (member is BaseFieldDeclarationSyntax field)
                    initialized = !field.Modifiers.Any(SyntaxKind.ConstKeyword) && field.Declaration.Variables.Any(v => v.Initializer != null);
                else
                    initialized = member is PropertyDeclarationSyntax property && property.Initializer != null;
                if (!initialized)
                    continue;
                if (member.Modifiers.Any(SyntaxKind.StaticKeyword))
                    shared = true;
                else
                    instance = true;
            }
            var at = type.OpenBraceToken;
            if (at.IsMissing)
                return;
            if (shared)
                edits.Add(new Edit(at.Span.End, InitField(true), at.SpanStart, edits.Count));
            if (instance && !type.Modifiers.Any(SyntaxKind.StaticKeyword))
                edits.Add(new Edit(at.Span.End, InitField(false), at.SpanStart, edits.Count));
        }

        static string InitField(bool isStatic) =>
            "private " + (isStatic ? "static " : "") + "readonly bool " + InitPrefix + Interlocked.Increment(ref _initFields) + " = " + ExecutionGuard.InitCheck + ";";

        /// <summary>
        /// Whether a catch clause can catch the guard's stops (<c>TimeoutException</c>, <c>InsufficientExecutionStackException</c>):
        /// no declaration, or one of their types or base types. Only those get the filter.
        /// </summary>
        static bool CatchesGuardStops(CatchClauseSyntax handler)
        {
            var type = handler.Declaration?.Type;
            if (type == null)
                return true;
            var name = type is QualifiedNameSyntax qualified ? qualified.Right : type is AliasQualifiedNameSyntax alias ? alias.Name : type;
            var text = (name as IdentifierNameSyntax)?.Identifier.ValueText;
            return text == "Exception" || text == "SystemException" || text == "TimeoutException" || text == "InsufficientExecutionStackException";
        }

        /// <summary><c>{ int counter = N; loop }</c>, the body starting with the counter's check.</summary>
        static void Loop(StatementSyntax loop, StatementSyntax body, List<Edit> edits)
        {
            var counter = CounterPrefix + edits.Count; // unique in the tree: nested loops each count on their own
            Wrap(loop, ExecutionGuard.LoopCounter(counter), loop.SpanStart, edits);
            var check = ExecutionGuard.LoopCheck(counter);
            if (body is BlockSyntax block)
                edits.Add(new Edit(block.OpenBraceToken.Span.End, check, loop.SpanStart, edits.Count));
            else
                Wrap(body, check, loop.SpanStart, edits);
        }

        /// <summary><c>{ call statement }</c>: the statement may be an embedded one (<c>if (x) goto L;</c>).</summary>
        static void Wrap(StatementSyntax statement, string call, int mapTo, List<Edit> edits)
        {
            edits.Add(new Edit(statement.SpanStart, "{ " + call, mapTo, edits.Count));
            edits.Add(new Edit(statement.Span.End, "}", statement.Span.End, edits.Count, closer: true));
        }

        static void Function(BlockSyntax? body, ArrowExpressionClauseSyntax? arrow, SyntaxToken semicolon, bool returnsValue, List<Edit> edits)
        {
            if (body != null)
            {
                edits.Add(new Edit(body.OpenBraceToken.Span.End, ExecutionGuard.CallCheck, body.OpenBraceToken.SpanStart, edits.Count));
                return;
            }
            if (arrow == null || semicolon.IsMissing || semicolon.Span.Length == 0)
                return;
            // `=> expr;` becomes `{ check; return expr; }`.
            ToBlock(arrow.Expression, arrow.ArrowToken.SpanStart, arrow.ArrowToken.Span.Length, semicolon.Span.End, "{ ", "}", returnsValue, edits);
        }

        /// <summary>
        /// <c>x => expr</c> becomes <c>x => { check; return expr; }</c> (<c>{ check; expr; }</c> without a value) when it is
        /// a delegate: a block cannot be an expression tree, also not inside one (an enclosing lambda or query that is one).
        /// </summary>
        static void ExpressionLambda(LambdaExpressionSyntax lambda, ExpressionSyntax body, Semantics semantics, List<Edit> edits)
        {
            if (semantics.HasErrors)
                return;
            foreach (var outer in lambda.AncestorsAndSelf())
            {
                if (outer is InterpolationSyntax || outer is QueryExpressionSyntax)
                    return; // a hole may not span lines (see Write); a query may be an expression tree
                if (outer is AnonymousFunctionExpressionSyntax function && !semantics.IsDelegate(function))
                    return;
            }
            if (!(semantics.Model.GetSymbolInfo(lambda).Symbol is IMethodSymbol method) || method.ReturnType.TypeKind == TypeKind.Error)
                return;
            // Every async lambda without a value returns a non-generic task type (Arity: a nested type of a generic one is not).
            var value = !method.ReturnsVoid && !(method.IsAsync && method.ReturnType is INamedTypeSymbol { Arity: 0 });
            ToBlock(body, body.SpanStart, 0, body.Span.End, "{ ", "; }", value, edits);
        }

        /// <summary><c>T P => expr;</c> becomes <c>T P { get { check; return expr; } }</c> (indexers alike).</summary>
        static void Getter(ArrowExpressionClauseSyntax arrow, SyntaxToken semicolon, List<Edit> edits)
        {
            if (semicolon.IsMissing || semicolon.Span.Length == 0)
                return;
            ToBlock(arrow.Expression, arrow.ArrowToken.SpanStart, arrow.ArrowToken.Span.Length, semicolon.Span.End, "{ get { ", "} }", true, edits);
        }

        /// <summary>
        /// An expression body becomes a block that starts with the call check: <paramref name="open"/> replaces
        /// <paramref name="remove"/> characters at <paramref name="start"/>, <paramref name="close"/> goes at <paramref name="end"/>.
        /// The expression is returned when it is a value (<c>{ check; expr; }</c> otherwise; <c>throw x;</c> is a statement).
        /// </summary>
        static void ToBlock(ExpressionSyntax expression, int start, int remove, int end, string open, string close, bool value, List<Edit> edits)
        {
            value = value && !(expression is ThrowExpressionSyntax);
            edits.Add(new Edit(start, open + ExecutionGuard.CallCheck + (value ? " return" : ""), start, edits.Count, remove: remove));
            edits.Add(new Edit(end, close, end, edits.Count, closer: true));
        }

        /// <summary>
        /// Whether <c>=> expr</c> of this signature is a value: not <c>void</c>; for <c>async</c>, only a generic task type
        /// (<c>Task&lt;T&gt;</c>, <c>UniTask&lt;T&gt;</c>): every async method without a value returns a non-generic one.
        /// The semantic model decides when there is one (an alias of <c>Task&lt;int&gt;</c>), else the syntax.
        /// </summary>
        static bool ReturnsValue(TypeSyntax type, SyntaxTokenList modifiers, Semantics? semantics)
        {
            if (type is PredefinedTypeSyntax predefined && predefined.Keyword.IsKind(SyntaxKind.VoidKeyword))
                return false;
            if (!modifiers.Any(SyntaxKind.AsyncKeyword))
                return true;
            if (semantics?.IsGenericTask(type) is bool generic)
                return generic;
            var name = type is QualifiedNameSyntax qualified ? qualified.Right : type is AliasQualifiedNameSyntax alias ? alias.Name : type;
            return name is GenericNameSyntax;
        }

        /// <summary>A directive that maps the next line like <paramref name="position"/> is mapped (or hides it).</summary>
        static void AppendLine(StringBuilder sb, SyntaxTree tree, int position)
        {
            if (tree.GetLineVisibility(position) == LineVisibility.Hidden)
            {
                sb.Append("#line hidden\n");
                return;
            }
            // The file name is taken verbatim (no escapes); Write skips trees whose path holds a `"`.
            var mapped = tree.GetMappedLineSpan(new TextSpan(position, 0));
            sb.Append("#line ").Append(mapped.StartLinePosition.Line + 1).Append(" \"").Append(mapped.Path).Append("\"\n");
        }
    }
